From a4513320423a388ed55eb0754353f46b10d05a99 Mon Sep 17 00:00:00 2001
From: Sylwester Nawrocki <s.nawrocki@samsung.com>
Date: Wed, 2 Nov 2016 12:03:03 +0100
Subject: [PATCH] ASoC: samsung: spdif: Fix DMA filter initialization
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

This patch fixes issues introduced in commit 73f5dfc68316bef2ab7062ec
"ASoC: samsung: get access to DMA engine early to defer probe properly"
and indicated by a following compilation warning:

  CC [M]  sound/soc/samsung/spdif.o
sound/soc/samsung/spdif.c: In function ‘spdif_probe’:
sound/soc/samsung/spdif.c:419:6: warning: ‘filter’ may be used uninitialized
in this function [-Wuninitialized]

Signed-off-by: Sylwester Nawrocki <s.nawrocki@samsung.com>
Signed-off-by: Mark Brown <broonie@kernel.org>

diff --git a/sound/soc/samsung/spdif.c b/sound/soc/samsung/spdif.c
index 704b7b12bf8b..779504f54bc0 100644
--- a/sound/soc/samsung/spdif.c
+++ b/sound/soc/samsung/spdif.c
@@ -416,6 +416,15 @@ static int spdif_probe(struct platform_device *pdev)
 		goto err3;
 	}

+	spdif_stereo_out.addr_width = 2;
+	spdif_stereo_out.addr = mem_res->start + DATA_OUTBUF;
+	filter = NULL;
+	if (spdif_pdata) {
+		spdif_stereo_out.filter_data = spdif_pdata->dma_playback;
+		filter = spdif_pdata->dma_filter;
+	}
+	spdif->dma_playback = &spdif_stereo_out;
+
 	ret = samsung_asoc_dma_platform_register(&pdev->dev, filter,
 						 NULL, NULL);
 	if (ret) {
@@ -432,16 +441,6 @@ static int spdif_probe(struct platform_device *pdev)
 		goto err4;
 	}

-	spdif_stereo_out.addr_width = 2;
-	spdif_stereo_out.addr = mem_res->start + DATA_OUTBUF;
-	filter = NULL;
-	if (spdif_pdata) {
-		spdif_stereo_out.filter_data = spdif_pdata->dma_playback;
-		filter = spdif_pdata->dma_filter;
-	}
-
-	spdif->dma_playback = &spdif_stereo_out;
-
 	return 0;
 err4:
 	iounmap(spdif->regs);
-- 
2.25.1

### Modifications in Each File

**File: `sound/soc/samsung/spdif.c`**
- The patch modifies the `spdif_probe` function by moving the initialization of `spdif_stereo_out` and the `filter` variable to an earlier point in the function.
- Specifically, the following lines were added to initialize `spdif_stereo_out` and `filter`:
  ```c
  spdif_stereo_out.addr_width = 2;
  spdif_stereo_out.addr = mem_res->start + DATA_OUTBUF;
  filter = NULL;
  if (spdif_pdata) {
      spdif_stereo_out.filter_data = spdif_pdata->dma_playback;
      filter = spdif_pdata->dma_filter;
  }
  spdif->dma_playback = &spdif_stereo_out;
  ```
- The previous initialization of these variables, which was located later in the function, has been removed to prevent the use of uninitialized variables, addressing a compilation warning.

### Relationships Between Modifications
- The modifications are directly related to fixing a bug introduced in a previous commit that caused a compilation warning about the potential use of an uninitialized variable (`filter`). By moving the initialization code earlier in the `spdif_probe` function, the patch ensures that `filter` is properly initialized before it is used, thus resolving the warning and ensuring correct functionality of the DMA filter initialization process.

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The root cause of the bug is the potential use of the `filter` variable without being initialized, which can lead to undefined behavior or incorrect operation in the `spdif_probe` function. The previous commit did not properly set these variables before they were referenced in a function, causing a compilation warning due to the risk of using uninitialized data.

        Commit message:
        ASoC: samsung: spdif: Fix DMA filter initialization
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

This patch fixes issues introduced in commit 73f5dfc68316bef2ab7062ec
"ASoC: samsung: get access to DMA engine early to defer probe properly"
and indicated by a following compilation warning:

  CC [M]  sound/soc/samsung/spdif.o
sound/soc/samsung/spdif.c: In function ‘spdif_probe’:
sound/soc/samsung/spdif.c:419:6: warning: ‘filter’ may be used uninitialized
in this function [-Wuninitialized]

Signed-off-by: Sylwester Nawrocki <s.nawrocki@samsung.com>
Signed-off-by: Mark Brown <broonie@kernel.org>  

        Patch:

 static int spdif_probe(struct platform_device *pdev)
 {
 	struct s3c_audio_pdata *spdif_pdata;
 	struct resource *mem_res;
 	struct samsung_spdif_info *spdif;
 	dma_filter_fn filter;
 	int ret;

 	spdif_pdata = pdev->dev.platform_data;

 	dev_dbg(&pdev->dev, "Entered %s\n", __func__);

 	mem_res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
 	if (!mem_res) {
 		dev_err(&pdev->dev, "Unable to get register resource.\n");
 		return -ENXIO;
 	}

 	if (spdif_pdata && spdif_pdata->cfg_gpio
 			&& spdif_pdata->cfg_gpio(pdev)) {
 		dev_err(&pdev->dev, "Unable to configure GPIO pins\n");
 		return -EINVAL;
 	}

 	spdif = &spdif_info;
 	spdif->dev = &pdev->dev;

 	spin_lock_init(&spdif->lock);

 	spdif->pclk = devm_clk_get(&pdev->dev, "spdif");
 	if (IS_ERR(spdif->pclk)) {
 		dev_err(&pdev->dev, "failed to get peri-clock\n");
 		ret = -ENOENT;
 		goto err0;
 	}
 	clk_prepare_enable(spdif->pclk);

 	spdif->sclk = devm_clk_get(&pdev->dev, "sclk_spdif");
 	if (IS_ERR(spdif->sclk)) {
 		dev_err(&pdev->dev, "failed to get internal source clock\n");
 		ret = -ENOENT;
 		goto err1;
 	}
 	clk_prepare_enable(spdif->sclk);

 	/* Request S/PDIF Register's memory region */
 	if (!request_mem_region(mem_res->start,
 				resource_size(mem_res), "samsung-spdif")) {
 		dev_err(&pdev->dev, "Unable to request register region\n");
 		ret = -EBUSY;
 		goto err2;
 	}

 	spdif->regs = ioremap(mem_res->start, 0x100);
 	if (spdif->regs == NULL) {
 		dev_err(&pdev->dev, "Cannot ioremap registers\n");
 		ret = -ENXIO;
 		goto err3;
 	}

+	spdif_stereo_out.addr_width = 2;
+	spdif_stereo_out.addr = mem_res->start + DATA_OUTBUF;
+	filter = NULL;
+	if (spdif_pdata) {
+		spdif_stereo_out.filter_data = spdif_pdata->dma_playback;
+		filter = spdif_pdata->dma_filter;
+	}
+	spdif->dma_playback = &spdif_stereo_out;
+
 	ret = samsung_asoc_dma_platform_register(&pdev->dev, filter,
 						 NULL, NULL);
 	if (ret) {
 		dev_err(&pdev->dev, "failed to register DMA: %d\n", ret);
 		goto err4;
 	}

 	dev_set_drvdata(&pdev->dev, spdif);

 	ret = devm_snd_soc_register_component(&pdev->dev,
 			&samsung_spdif_component, &samsung_spdif_dai, 1);
 	if (ret != 0) {
 		dev_err(&pdev->dev, "fail to register dai\n");
 		goto err4;
 	}

-	spdif_stereo_out.addr_width = 2;
-	spdif_stereo_out.addr = mem_res->start + DATA_OUTBUF;
-	filter = NULL;
-	if (spdif_pdata) {
-		spdif_stereo_out.filter_data = spdif_pdata->dma_playback;
-		filter = spdif_pdata->dma_filter;
-	}
-
-	spdif->dma_playback = &spdif_stereo_out;
-
 	return 0;
 err4:
 	iounmap(spdif->regs);
 err3:
 	release_mem_region(mem_res->start, resource_size(mem_res));
 err2:
 	clk_disable_unprepare(spdif->sclk);
 err1:
 	clk_disable_unprepare(spdif->pclk);
 err0:
 	return ret;
 }



